from django.db import migrations, models
from django.utils import timezone


def give_open_visits_a_pin(apps, schema_editor):
    """Visitors still on site when PINs arrived get one, so they can check out at the kiosk too."""
    Visit = apps.get_model("core", "Visit")
    taken = {}
    for visit in Visit.objects.filter(checked_out_at__isnull=True, valid_until__gte=timezone.now(), pin=""):
        used = taken.setdefault(visit.condominium_id, set())
        pin = f"{secrets.randbelow(10_000):04d}"
        while pin in used:
            pin = f"{secrets.randbelow(10_000):04d}"
        used.add(pin)
        visit.pin = pin
        visit.save(update_fields=["pin"])


